var s=`1132-corn-dogs`;var n=`world-1132`;var t=`US`;var o=`northern-america`;var r=8;var a=30;var l={en:`Corn Dogs`,ua:`Корн-доги`};var g={en:`Corn Dogs is a dish from United States prepared with cornmeal, all-purpose flour, baking powder, whole cow milk. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Корн-доги, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: кукурудзяна крупа дрібного помелу, пшеничне борошно універсальне, розпушувач тіста, цільне коров'яче молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var h=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:9,i:[[`cornmeal`,200,`g`],[`all-purpose-flour`,160,`g`],[`baking-powder`,10,`g`],[`whole-cow-milk`,320,`ml`],[`chicken-egg`,1,`pcs`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:6,i:[[`hot-dog-sausage`,8,`pcs`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 13 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 13 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:13,i:[[`canola-oil`,850,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`yellow-mustard`,80,`g`]]}];var d={slug:s,id:n,country:`US`,region:o,servings:8,minutes:30,title:l,text:g,steps:h};export{t as country,d as default,n as id,a as minutes,o as region,r as servings,s as slug,h as steps,g as text,l as title};